#include <stdint.h>
#include <string.h>

#include <pbl/bluetooth/prf_store.h>

#include <host/ble_hs.h>
#include <host/ble_store.h>
#include <syscfg/syscfg.h>

// NimBLE's private header, which needs the ones above.
// clang-format off
#include "ble_store_config_priv.h"
// clang-format on

#define KEY_SIZE 16

#define FLAG_SECURE_CONNECTIONS 0x01U
#define FLAG_AUTHENTICATED      0x02U

/* The PRF store keeps one bonding: the last one of the store. */
static int prv_save(void) {
  struct pbl_bt_sm_pairing_info info = {};
  const struct ble_store_value_sec *peer;
  uint8_t flags = 0U;

  if (ble_store_config_num_peer_secs == 0) {
    if (ble_store_config_num_our_secs == 0) {
      pbl_bt_prf_store_erase_pairing();
    }
    return 0;
  }

  peer = &ble_store_config_peer_secs[ble_store_config_num_peer_secs - 1];

  info.identity.is_random_address = peer->peer_addr.type == BLE_ADDR_RANDOM;
  memcpy(info.identity.address.octets, peer->peer_addr.val, sizeof(info.identity.address.octets));

  if (peer->ltk_present) {
    info.is_remote_encryption_info_valid = true;
    info.remote_encryption_info.ediv = peer->ediv;
    info.remote_encryption_info.rand = peer->rand_num;
    memcpy(info.remote_encryption_info.ltk.data, peer->ltk, KEY_SIZE);
  }

  if (peer->irk_present) {
    info.is_remote_identity_info_valid = true;
    memcpy(info.irk.data, peer->irk, KEY_SIZE);
  }

  for (int i = 0; i < ble_store_config_num_our_secs; i++) {
    const struct ble_store_value_sec *our = &ble_store_config_our_secs[i];

    if (ble_addr_cmp(&our->peer_addr, &peer->peer_addr) == 0 && our->ltk_present) {
      info.is_local_encryption_info_valid = true;
      info.local_encryption_info.ediv = our->ediv;
      info.local_encryption_info.rand = our->rand_num;
      memcpy(info.local_encryption_info.ltk.data, our->ltk, KEY_SIZE);
      break;
    }
  }

  if (peer->sc) {
    flags |= FLAG_SECURE_CONNECTIONS;
  }
  if (peer->authenticated) {
    flags |= FLAG_AUTHENTICATED;
  }

  pbl_bt_prf_store_set_pairing(&info, nullptr, flags);

  return 0;
}

int ble_store_config_persist_our_secs(void) {
  return prv_save();
}

int ble_store_config_persist_peer_secs(void) {
  return prv_save();
}

int ble_store_config_persist_cccds(void) {
  return 0;
}

/* The local IRK is the identity root key. LTKs and CSRKs are generated by NimBLE. */
static int prv_gen_key(uint8_t key, struct ble_store_gen_key *gen_key, uint16_t conn_handle) {
  struct pbl_bt_sm_key keys[PBL_BT_SM_ROOT_KEY_TYPE_NUM];

  if (key != BLE_STORE_GEN_KEY_IRK) {
    return BLE_HS_ENOTSUP;
  }

  if (!pbl_bt_prf_store_get_root_key(PBL_BT_SM_ROOT_KEY_TYPE_IDENTITY,
                                     &keys[PBL_BT_SM_ROOT_KEY_TYPE_IDENTITY])) {
    int rc;

    rc = ble_hs_hci_rand(keys, sizeof(keys));
    if (rc != 0) {
      return rc;
    }

    pbl_bt_prf_store_set_root_keys(keys);
  }

  memcpy(gen_key->irk, keys[PBL_BT_SM_ROOT_KEY_TYPE_IDENTITY].data, KEY_SIZE);

  return 0;
}

void ble_store_config_conf_init(void) {
  struct pbl_bt_sm_pairing_info info;
  struct ble_store_value_sec *sec;
  ble_addr_t addr;
  uint8_t flags;

  ble_hs_cfg.store_gen_key_cb = prv_gen_key;

  if (!pbl_bt_prf_store_get_pairing(&info, nullptr, &flags)) {
    return;
  }

  addr.type = info.identity.is_random_address ? BLE_ADDR_RANDOM : BLE_ADDR_PUBLIC;
  memcpy(addr.val, info.identity.address.octets, sizeof(addr.val));

  sec = &ble_store_config_peer_secs[0];
  memset(sec, 0, sizeof(*sec));
  sec->peer_addr = addr;
  sec->key_size = KEY_SIZE;
  sec->sc = (flags & FLAG_SECURE_CONNECTIONS) != 0U;
  sec->authenticated = (flags & FLAG_AUTHENTICATED) != 0U;
  if (info.is_remote_encryption_info_valid) {
    sec->ediv = info.remote_encryption_info.ediv;
    sec->rand_num = info.remote_encryption_info.rand;
    sec->ltk_present = 1;
    memcpy(sec->ltk, info.remote_encryption_info.ltk.data, KEY_SIZE);
  }
  if (info.is_remote_identity_info_valid) {
    sec->irk_present = 1;
    memcpy(sec->irk, info.irk.data, KEY_SIZE);
  }
  ble_store_config_num_peer_secs = 1;

  if (!info.is_local_encryption_info_valid) {
    return;
  }

  sec = &ble_store_config_our_secs[0];
  memset(sec, 0, sizeof(*sec));
  sec->peer_addr = addr;
  sec->key_size = KEY_SIZE;
  sec->sc = (flags & FLAG_SECURE_CONNECTIONS) != 0U;
  sec->authenticated = (flags & FLAG_AUTHENTICATED) != 0U;
  sec->ediv = info.local_encryption_info.ediv;
  sec->rand_num = info.local_encryption_info.rand;
  sec->ltk_present = 1;
  memcpy(sec->ltk, info.local_encryption_info.ltk.data, KEY_SIZE);
  ble_store_config_num_our_secs = 1;
}
